@@ -0,0 +1,39 @@
+import { expect, test } from "bun:test";
+import { hostedStreamEvents, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+
+const failure = async () => new Error("service failed");
+
+test("reads ahead for signed rows without reordering blocks and reports only incoming chunks", async () => {
+  const signed: SignedBlock[] = [];
+  let progress = 0;
+  async function* events(): AsyncGenerator<StepEvent> {
+    yield { kind: "item", item: { kind: "thinking", index: 0, text: "Think" } };
+    yield { kind: "item", item: { kind: "text", index: 2, text: "Answer" } };
+    await Bun.sleep(30_000);
+    expect(progress).toBe(2);
+    signed.push({ type: "thinking", thinking: "Thinking", signature: "signed" }, { type: "redacted_thinking", data: "opaque" });
+    yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+  }
+  const output = await Array.fromAsync(hostedStreamEvents(events(), { read: () => signed }, 0, "model", failure, () => {}, () => { progress++; }));
+  expect(progress).toBe(3);
+  expect(output.filter((event) => event.type === "content_block_start").map((event) => event.content_block.type)).toEqual(["thinking", "redacted_thinking", "text"]);
+  const signature = output.findIndex((event) => event.type === "content_block_delta" && event.delta.type === "signature_delta");
+  expect(output[signature + 1]).toEqual({ type: "content_block_stop", index: 0 });
+  expect(output[signature + 2]).toMatchObject({ type: "content_block_start", index: 1, content_block: { data: "opaque" } });
+  expect(output.at(-1)?.type).toBe("message_stop");
+}, 40_000);
+
+test("a missing row after completion is transient, but a missing stop preserves the service failure", async () => {
+  for (const stopped of [true, false]) {
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Think" } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "Answer" } };
+      if (stopped) yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+      yield { kind: "done" };
+    }
+    const result = Array.fromAsync(hostedStreamEvents(events(), { read: () => [] }, 0, "model", failure, () => {}, () => {}));
+    if (stopped) await expect(result).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    else await expect(result).rejects.toThrow("service failed");
+  }
+});

