+function transcript() {
+  const folder = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+  folders.push(folder);
+  const path = join(folder, "agent.jsonl");
+  writeFileSync(path, "");
+  return {
+    rows: agentRows(path, 0),
+    append: (content: SignedBlock[]) => { appendFileSync(path, `${JSON.stringify({ type: "assistant", message: { content } })}\n`); },
+  };
