+  });
+
+  test("a step ending without stop preserves the service failure even while a signature is pending", async () => {
+    const file = transcript();
+    async function* chunks(): AsyncGenerator<StepEvent> {
+      yield item({ kind: "thinking", index: 0, text: "thought" });
+      yield item({ kind: "text", index: 1, text: "answer" });
