+    /** @yields {StepEvent} A complete response whose signed row is missing. */
+    async function* source(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Thought" } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "Answer" } };
+      stopped = true;
+      yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+    }
+    const output = Array.fromAsync(hostedStreamEvents(source(), agentRows(agentFile(), 0), 0, MODEL.id, async () => SERVICE_FAILURE, () => { throw new Error("A failed response cannot answer"); }, () => {}));
+    await expect(output).rejects.toBeInstanceOf(LlmStreamError);
+    await expect(output).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    expect(stopped).toBe(true);
+  });
+
+  test.each(["done", "exhausted"])("a step that ends %s without a stop chunk reports the service failure, even with a pending row", async (ending) => {
+    /** @yields {StepEvent} An incomplete response whose signed row is missing. */
+    async function* source(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Thought" } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "Incomplete" } };
+      if (ending === "done") yield { kind: "done" };
+    }
+    await expect(Array.fromAsync(hostedStreamEvents(source(), agentRows(agentFile(), 0), 0, MODEL.id, async () => SERVICE_FAILURE, () => {}, () => {}))).rejects.toBe(SERVICE_FAILURE);
+  });
+
+  test("unsigned text is streamed before the step ends", async () => {
+    let stopped = false;
+    /** @yields {StepEvent} Text that needs no signed row. */
+    async function* source(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "text", index: 0, text: "Answer" } };
+      stopped = true;
+      yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+    }
+    const stream = hostedStreamEvents(source(), agentRows(agentFile(), 0), 0, MODEL.id, async () => SERVICE_FAILURE, () => {}, () => {});
+    expect((await stream.next()).value?.type).toBe("message_start");
+    expect((await stream.next()).value?.type).toBe("content_block_start");
+    expect((await stream.next()).value).toMatchObject({ type: "content_block_delta", delta: { type: "text_delta", text: "Answer" } });
