+    hosted: true,
+    operations: {
+      createStream: async (_params, options) => ({
+        data: Object.assign(hostedStreamEvents(source(options.signal), agentRows(path, 0), 0, MODEL.id, async () => SERVICE_FAILURE, () => {}, () => { options.onProgress?.(); }), { controller: new AbortController() }),
+        response: new Response(null),
+      }),
+      isBadRequestError: () => false,
+    },
+  });
+  return adapter.streamWithTools({ messages: [{ kind: "user", origin: "human", content: "Answer" }], systemPrompt: { stable: "", session: "", conversation: "" }, tools: [], reasoningEffort: "medium" });
+}
