+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "100";
+    /** @yields {StepEvent} A response that keeps writing while its signed row is pending. */
+    async function* source(signal: AbortSignal): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: SIGNED.thinking } };
+      for (let index = 0; index < 20; index += 1) {
+        await awaitWithAbortSignal(Bun.sleep(15), signal);
+        yield { kind: "item", item: { kind: "text", index: 1, text: "A" } };
+      }
+      writeSigned(path, [SIGNED]);
+      yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+    }
+    try {
+      const output: ProviderStreamEvent[] = await Array.fromAsync(await adapterStream(path, source));
+      expect(output.filter((event) => event.kind === "text_delta").map((event) => event.text).join("")).toBe("A".repeat(20));
+      expect(output.some((event) => event.kind === "thinking_complete")).toBe(true);
+    } finally {
+      if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+      else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+    }
+  });
+
+  test("silence while a signed row is pending still fails as a thinking stall", async () => {
+    const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "50";
+    /** @yields {StepEvent} A response that stops writing before its signed row arrives. */
+    async function* source(signal: AbortSignal): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Thought" } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "Partial" } };
