+++ b/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts
@@ -0,0 +1,86 @@
+import { expect, test } from "bun:test";
+import { setTimeout as delay } from "node:timers/promises";
+import { withStreamAttempt } from "../../../../../../src/orchestration/agent-runtime/llm/stream-attempt.js";
+import { armStreamLiveness } from "../../../../../../src/orchestration/agent-runtime/llm/stream-liveness.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+
+const failure = async () => new Error("service failed");
+
+test("holds later blocks until the step supplies signed rows, reporting actual chunk progress", async () => {
+  const signed: SignedBlock[] = [];
+  let progress = 0;
+  let answer: HostedAnswer | undefined;
+  async function* events(): AsyncGenerator<StepEvent> {
+    yield { kind: "item", item: { kind: "thinking", index: 0, text: "think" } };
+    yield { kind: "item", item: { kind: "text", index: 2, text: "hello" } };
+    yield { kind: "item", item: { kind: "text", index: 2, text: " world" } };
+    signed.push({ type: "thinking", thinking: "thinking", signature: "signed" }, { type: "redacted_thinking", data: "redacted" });
+    yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+  }
+  const output = await Array.fromAsync(hostedStreamEvents(events(), { read: () => signed }, 0, "model", failure, (value) => { answer = value; }, () => { progress += 1; }));
+  expect(progress).toBeGreaterThan(0);
+  expect(output.filter((event) => event.type === "content_block_start" || event.type === "content_block_stop" || (event.type === "content_block_delta" && event.delta.type === "signature_delta"))).toEqual([
+    { type: "content_block_start", index: 0, content_block: { type: "thinking", thinking: "", signature: "" } },
+    { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "signed" } },
+    { type: "content_block_stop", index: 0 },
+    { type: "content_block_start", index: 1, content_block: { type: "redacted_thinking", data: "redacted" } },
+    { type: "content_block_stop", index: 1 },
+    { type: "content_block_start", index: 2, content_block: { type: "text", text: "", citations: null } },
+    { type: "content_block_stop", index: 2 },
+  ]);
+  expect(answer?.message.content).toEqual([...signed, { type: "text", text: "hello world" }]);
+});
+
+for (const terminal of ["stop", "done", "eof"] as const) {
+  test(`missing signed row at ${terminal} reports the correct failure`, async () => {
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "think" } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "answer" } };
+      if (terminal === "stop") yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+      if (terminal === "done") yield { kind: "done" };
+    }
+    const result = Array.fromAsync(hostedStreamEvents(events(), { read: () => [] }, 0, "model", failure, () => {}, () => {}));
+    if (terminal === "stop") await expect(result).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    else await expect(result).rejects.toThrow("service failed");
+  });
+}
+
+for (const stalls of [false, true]) {
+  test(`pending rows ${stalls ? "do not conceal a thinking stall" : "report chunks beyond the thinking deadline"}`, async () => {
+    const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "100";
+    try {
+      const result = Array.fromAsync(withStreamAttempt(async function* (attempt) {
+        const liveness = armStreamLiveness(attempt, { label: "hosted-stream-test", provider: "Anthropic", telemetry: undefined });
+        const signed: SignedBlock[] = [];
+        async function* events(): AsyncGenerator<StepEvent> {
+          yield { kind: "item", item: { kind: "thinking", index: 0, text: "think" } };
+          yield { kind: "item", item: { kind: "text", index: 1, text: "answer" } };
+          for (let index = 0; index < 15; index += 1) {
+            await delay(stalls ? 1000 : 20, undefined, { signal: attempt.signal });
+            yield { kind: "item", item: { kind: "text", index: 1, text: "." } };
+          }
+          signed.push({ type: "thinking", thinking: "think", signature: "signature" });
+          yield { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+        }
+        try {
+          for await (const event of hostedStreamEvents(events(), { read: () => signed }, 0, "model", failure, () => {}, () => { liveness.frame(); })) {
+            liveness.frame();
+            if (event.type === "content_block_start" && event.content_block.type === "thinking") liveness.begin(String(event.index));
+            if (event.type === "content_block_stop") liveness.complete(String(event.index));
+            yield event;
+          }
+        } catch (error) {
+          attempt.throwIfStreamTimedOut();
+          throw error;
+        }
+      }, {}));
+      if (stalls) await expect(result).rejects.toThrow("thinking block stalled after 100ms");
+      else expect((await result).at(-1)).toEqual({ type: "message_stop" });
+    } finally {
+      if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+      else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+    }
+  });
+}

