+import { describe, expect, spyOn, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+
+const signed: SignedBlock = { type: "thinking", thinking: "Thought.", signature: "signed" };
+const stop: StepEvent = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+const thinking: StepEvent = { kind: "item", item: { kind: "thinking", index: 0, text: "Thought." } };
+const text = (value: string, index = 1): StepEvent => ({ kind: "item", item: { kind: "text", index, text: value } });
+const failure = async () => new Error("service failure");
+
+async function collect(events: AsyncIterable<Anthropic.RawMessageStreamEvent>) {
+  const result: Anthropic.RawMessageStreamEvent[] = [];
+  for await (const event of events) result.push(event);
+  return result;
+}
+
+describe("hosted response signatures", () => {
+  test("consumes a long answer before its signed rows arrive, preserving block order and reporting only incoming progress", async () => {
+    let now = 0;
+    const clock = spyOn(Date, "now").mockImplementation(() => now);
+    const sleep = spyOn(Bun, "sleep").mockImplementation(async () => { now += 1_000; });
+    const rows: SignedBlock[] = [];
+    const progress: number[] = [];
+    let answer: HostedAnswer | undefined;
+    async function* input(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text("First.");
+      now += 90_000;
+      yield text(" Last.");
+      rows.push(signed, { type: "redacted_thinking", data: "opaque" });
+      yield text("After redaction.", 3);
+      yield stop;
+    }
+    try {
+      const output = await collect(hostedStreamEvents(input(), { read: () => rows }, 0, "model", failure, (value) => { answer = value; }, () => { progress.push(now); }));
+      expect(output.filter((event) => event.type === "content_block_start").map((event) => event.content_block.type)).toEqual(["thinking", "text", "redacted_thinking", "text"]);
+      const signature = output.findIndex((event) => event.type === "content_block_delta" && event.delta.type === "signature_delta" && event.delta.signature === "signed");
+      expect(signature).toBeGreaterThan(0);
+      expect(output[signature + 1]).toEqual({ type: "content_block_stop", index: 0 });
+      expect(output[signature + 2]).toMatchObject({ type: "content_block_start", index: 1 });
+      expect(answer?.message.content).toEqual([signed, { type: "text", text: "First. Last." }, { type: "redacted_thinking", data: "opaque" }, { type: "text", text: "After redaction." }]);
+      expect(progress).toHaveLength(5);
+      expect(output.at(-1)?.type).toBe("message_stop");
+    } finally {
+      clock.mockRestore();
+      sleep.mockRestore();
+    }
+  });
+
+  test("a missing row after stop fails transiently without reporting polling as progress", async () => {
+    let now = 0;
+    const clock = spyOn(Date, "now").mockImplementation(() => now);
+    const sleep = spyOn(Bun, "sleep").mockImplementation(async () => { now += 10_000; });
+    let progress = 0;
+    async function* input(): AsyncGenerator<StepEvent> { yield thinking; yield stop; }
+    try {
+      await expect(collect(hostedStreamEvents(input(), { read: () => [] }, 0, "model", failure, () => {}, () => { progress += 1; }))).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+      expect(progress).toBe(2);
+    } finally {
+      clock.mockRestore();
+      sleep.mockRestore();
+    }
+  });
+
+  test("an unfinished response waiting for a row throws the service failure, not a missing-row error", async () => {
+    let now = 0;
+    const clock = spyOn(Date, "now").mockImplementation(() => now);
+    const sleep = spyOn(Bun, "sleep").mockImplementation(async () => { now += 10_000; });
+    async function* input(): AsyncGenerator<StepEvent> { yield thinking; yield text("Partial."); yield { kind: "done" }; }
+    try {
+      await expect(collect(hostedStreamEvents(input(), { read: () => [] }, 0, "model", failure, () => {}, () => {}))).rejects.toThrow("service failure");
+    } finally {
+      clock.mockRestore();
+      sleep.mockRestore();
+    }
+  });
+
+  test("polling a row while input is silent does not report progress", async () => {
+    let progress = 0;
+    let finish = () => {};
+    const waiting = new Promise<void>((resolve) => { finish = resolve; });
+    async function* input(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text("Partial.");
+      await waiting;
+      yield { kind: "done" };
+    }
+    const output = collect(hostedStreamEvents(input(), { read: () => [] }, 0, "model", failure, () => {}, () => { progress += 1; }));
+    try {
+      await Bun.sleep(80);
+      expect(progress).toBe(2);
+    } finally {
+      finish();
+      await expect(output).rejects.toThrow("service failure");
+    }
+  });
