+import { expect, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+
+const thinking: StepEvent = { kind: "item", item: { kind: "thinking", index: 0, text: "Reason" } };
+const text: StepEvent = { kind: "item", item: { kind: "text", index: 2, text: "Answer" } };
+const stop: StepEvent = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+
+test("reads ahead for signed rows while preserving block order and reporting only incoming chunks", async () => {
+  const signed: SignedBlock[] = [{ type: "thinking", thinking: "Earlier", signature: "old" }];
+  let progress = 0;
+  let answer: HostedAnswer | undefined;
+  async function* events(): AsyncGenerator<StepEvent> {
+    yield thinking;
+    yield text;
+    expect(progress).toBe(2);
+    await Bun.sleep(10);
+    expect(progress).toBe(2);
+    yield { kind: "item", item: { kind: "text", index: 2, text: " continued" } };
+    signed.push({ type: "thinking", thinking: "Reason fully", signature: "signature" }, { type: "redacted_thinking", data: "redacted" });
+    yield stop;
+  }
+  const output: Anthropic.RawMessageStreamEvent[] = [];
+  for await (const event of hostedStreamEvents(events(), { read: () => signed }, 1, "model", async () => new Error("service"), (value) => { answer = value; }, () => { progress += 1; })) output.push(event);
+  expect(progress).toBe(4);
+  expect(output.map((event) => event.type)).toEqual([
+    "message_start", "content_block_start", "content_block_delta", "content_block_delta", "content_block_delta", "content_block_stop",
+    "content_block_start", "content_block_stop", "content_block_start", "content_block_delta", "content_block_delta", "content_block_stop", "message_delta", "message_stop",
+  ]);
+  expect(output[4]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "signature" } });
+  expect(answer?.message.content).toEqual([
+    { type: "thinking", thinking: "Reason fully", signature: "signature" },
+    { type: "redacted_thinking", data: "redacted" },
+    { type: "text", text: "Answer continued" },
+  ]);
+}, 500);
+
+for (const endedWithStop of [true, false]) {
+  test(`missing signed row uses ${endedWithStop ? "transient row failure after stop" : "service failure without stop"}`, async () => {
+    const service = new Error("service rejected the request");
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text;
+      if (endedWithStop) yield stop;
+      yield { kind: "done" };
+    }
+    const consume = async () => {
+      for await (const _event of hostedStreamEvents(events(), { read: () => [] }, 0, "model", async () => service, () => {}, () => {})) {}
+    };
+    if (endedWithStop) await expect(consume()).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
