+import { agentRows, type SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+
+const serviceFailure = new Error("The service ended the request");
+const stop: StepEvent = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 11, output_tokens: 22, cache_creation_input_tokens: 0, cache_read_input_tokens: 0 } } };
+
+/** A real agent file with a virtual clock for generation and row-flush delays. */
+function fixture(virtualTime = true) {
+  const folder = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+  const path = join(folder, "agent.jsonl");
+  writeFileSync(path, "");
+  let now = 0;
+  let polls = 0;
+  const clock = virtualTime ? spyOn(Date, "now").mockImplementation(() => now) : undefined;
+  const sleep = virtualTime ? spyOn(Bun, "sleep").mockImplementation(async () => { now += 1_000; polls += 1; }) : undefined;
+  return {
+    rows: agentRows(path, 0),
+    append: (content: unknown[]) => appendFileSync(path, `${JSON.stringify({ type: "assistant", message: { content } })}\n`),
+    advance: (ms: number) => { now += ms; },
+    polls: () => polls,
+    close() { clock?.mockRestore(); sleep?.mockRestore(); rmSync(folder, { recursive: true, force: true }); },
+  };
+}
+
