+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "100";
+    const model: ModelInfo = {
+      provider: "anthropic", family: "anthropic", id: "claude-sonnet-5-5", name: "Claude Sonnet 5.5",
+      reasoning: true, toolCall: true, attachment: true, temperature: true, openWeights: false,
+      cost: { input: 0, output: 0 }, pricing: { status: "unavailable", reason: "missing-rate-card" },
