+  else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = thinkingTimeout;
+  for (const folder of folders.splice(0)) rmSync(folder, { recursive: true, force: true });
+});
+
+function transcript() {
+  const folder = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+  folders.push(folder);
+  const path = join(folder, "agent.jsonl");
+  writeFileSync(path, "");
+  return { path, rows: agentRows(path, 0) };
+}
+
+const thinking: StepEvent = { kind: "item", item: { kind: "thinking", index: 0, text: "Plan" } };
+const text: StepEvent = { kind: "item", item: { kind: "text", index: 1, text: "Answer" } };
+const stop: StepEvent = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+const serviceFailure = new Error("service rejected the request");
+
+async function collect<A>(events: AsyncIterable<A>) {
+  const result: A[] = [];
+  for await (const event of events) result.push(event);
+  return result;
+}
+
+describe("the hosted response stream", () => {
+  test("buffers later blocks until their signed rows arrive, without bounding active generation or reordering Anthropic events", async () => {
+    const { path, rows } = transcript();
