+  test.each(["done", "iterator end"])("an unsigned response that ends through %s without a stop chunk throws the service's answer", async (end) => {
+    using _time = clock();
+    async function* source(): AsyncGenerator<StepEvent> {
+      yield item({ kind: "thinking", index: 0, text: "Think" });
+      yield item({ kind: "text", index: 1, text: "Partial answer" });
+      if (end === "done") yield { kind: "done" };
+    }
+    await expect(collect(hostedStreamEvents(source(), { read: () => [] }, 0, "model", async () => serviceFailure, () => {}, () => {}))).rejects.toBe(serviceFailure);
+  });
+
+  test.each(["active", "stalled"])("the real thinking watchdog follows incoming chunks, not row polls (%s response)", async (state) => {
+    const stalled = state === "stalled";
+    const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "200";
+    let answered = false;
+    const signed: SignedBlock[] = [];
+    const run = () => collect(withStreamAttempt(async function* (attempt) {
+      const liveness = armStreamLiveness(attempt, { label: "hosted-stream-test", provider: "Anthropic", telemetry: undefined });
+      liveness.preStream();
+      async function* source(): AsyncGenerator<StepEvent> {
+        yield item({ kind: "thinking", index: 0, text: thinking.thinking });
+        await awaitWithAbortSignal(Bun.sleep(150), attempt.signal);
+        yield item({ kind: "text", index: 1, text: "A" });
+        if (stalled) await awaitWithAbortSignal(new Promise<void>(() => {}), attempt.signal);
+        await awaitWithAbortSignal(Bun.sleep(150), attempt.signal);
+        yield item({ kind: "text", index: 1, text: "B" });
+        signed.push(thinking);
+        yield item(stop);
+      }
+      const events = hostedStreamEvents(source(), { read: () => signed }, 0, "model", async () => serviceFailure, () => { answered = true; }, () => { liveness.frame(); });
+      for await (const event of events) {
+        liveness.frame();
+        if (event.type === "content_block_start" && event.content_block.type === "thinking") liveness.begin(String(event.index));
+        if (event.type === "content_block_delta" && event.delta.type === "thinking_delta") liveness.append(event.delta.thinking);
+        if (event.type === "content_block_stop") liveness.complete(String(event.index));
+        yield event;
+      }
+    }, {}));
+    try {
+      if (stalled) await expect(run()).rejects.toMatchObject({ cause: expect.any(ThinkingStallError) });
+      else await run();
+      expect(answered).toBe(!stalled);
+    } finally {
+      if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+      else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+    }
+  });
+});

