+import { expect, spyOn, test } from "bun:test";
+import { appendFileSync, writeFileSync } from "node:fs";
+import { join } from "node:path";
+import { Redacted } from "effect";
+import { abortableSleep } from "../../../../../../src/infra/abort.js";
+import type { ModelInfo } from "../../../../../../src/infra/llm/models.js";
+import { createAnthropicAdapter } from "../../../../../../src/orchestration/agent-runtime/llm/anthropic.js";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { CliBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/cli-view.js";
+import { agentRows } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+import { temporaryDirectories } from "../../../../../helpers/directories.js";
+
+const temporaryDirectory = temporaryDirectories();
+const serviceFailure = new Error("404 status code (no body)");
+const stop: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: null };
+
+function transcript() {
+  const path = join(temporaryDirectory("hosted-stream-"), "agent.jsonl");
+  writeFileSync(path, "");
+  return { rows: agentRows(path, 0), append: (content: readonly CliBlock[]) => { appendFileSync(path, JSON.stringify({ type: "assistant", message: { content } }) + "\n"); } };
+}
+
+/** @yields {StepEvent} Each hook chunk of one step. */
+async function* step(items: readonly HostStepItem[]): AsyncGenerator<StepEvent> {
+  for (const item of items) yield { kind: "item", item };
+}
+
+test("buffers later chunks for longer than a minute until signed rows arrive, then emits every block in Anthropic order", async () => {
+  const file = transcript();
+  file.append([{ type: "thinking", thinking: "Earlier step", signature: "earlier" }]);
+  const content: CliBlock[] = [
+    { type: "thinking", thinking: "Plan fully", signature: "plan-signature" },
+    { type: "redacted_thinking", data: "opaque-data" },
+    { type: "text", text: "Answer" },
+    { type: "thinking", thinking: "Check", signature: "check-signature" },
+    { type: "tool_use", id: "call-1", name: "read", input: { path: "file" } },
+  ];
+  let clock = 0;
+  const now = spyOn(Date, "now").mockImplementation(() => (clock += 90_000));
+  const progress: string[] = [];
+  const answers: HostedAnswer[] = [];
+  let arriving = "";
+  /** @yields {StepEvent} The signed rows become readable only after all content chunks. */
+  async function* delayedRows(): AsyncGenerator<StepEvent> {
+    const items: HostStepItem[] = [
+      { kind: "thinking", index: 0, text: "Plan" },
+      { kind: "text", index: 2, text: "An" },
+      { kind: "text", index: 2, text: "swer" },
+      { kind: "thinking", index: 3, text: "Check" },
+      { kind: "tool", index: 4, id: "call-1", name: "read" },
+      { kind: "input", index: 4, json: '{"path":"file"}' },
+    ];
+    for (const item of items) {
+      clock += 90_000;
+      arriving = item.kind;
+      yield { kind: "item", item };
+    }
+    file.append(content);
+    arriving = "stop";
+    yield { kind: "item", item: { kind: "stop", stopReason: "tool_use", usage: { input_tokens: 10, output_tokens: 20, cache_read_input_tokens: 30, cache_creation_input_tokens: 40 } } };
+  }
+  try {
+    const output = await Array.fromAsync(hostedStreamEvents(delayedRows(), file.rows, 1, "model", async () => serviceFailure, (answer) => { answers.push(answer); }, () => { progress.push(arriving); }));
+    expect(output[0]).toMatchObject({ type: "message_start", message: { model: "model" } });
+    expect(output.slice(1)).toMatchObject([
+      { type: "content_block_start", index: 0, content_block: { type: "thinking" } },
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "Plan" } },
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: " fully" } },
+      { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "plan-signature" } },
+      { type: "content_block_stop", index: 0 },
+      { type: "content_block_start", index: 1, content_block: { type: "redacted_thinking", data: "opaque-data" } },
+      { type: "content_block_stop", index: 1 },
+      { type: "content_block_start", index: 2, content_block: { type: "text" } },
+      { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: "An" } },
+      { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: "swer" } },
+      { type: "content_block_stop", index: 2 },
+      { type: "content_block_start", index: 3, content_block: { type: "thinking" } },
+      { type: "content_block_delta", index: 3, delta: { type: "thinking_delta", thinking: "Check" } },
+      { type: "content_block_delta", index: 3, delta: { type: "signature_delta", signature: "check-signature" } },
+      { type: "content_block_stop", index: 3 },
+      { type: "content_block_start", index: 4, content_block: { type: "tool_use", id: "call-1", name: "read" } },
+      { type: "content_block_delta", index: 4, delta: { type: "input_json_delta", partial_json: '{"path":"file"}' } },
+      { type: "content_block_stop", index: 4 },
+      { type: "message_delta", delta: { stop_reason: "tool_use" }, usage: { input_tokens: 10, output_tokens: 20, cache_read_input_tokens: 30, cache_creation_input_tokens: 40 } },
+      { type: "message_stop" },
+    ]);
+    expect(answers).toEqual([{ message: { role: "assistant", content }, stopReason: "tool_use" }]);
+    expect(progress).toEqual(["text", "text", "thinking", "tool", "input", "stop"]);
+  } finally {
+    now.mockRestore();
+  }
+});
+
+test("releases buffered text as soon as its preceding signature is readable, before the stop chunk", async () => {
+  const file = transcript();
+  let stopped = false;
+  const progress: string[] = [];
+  /** @yields {StepEvent} A row arrives between two text chunks. */
+  async function* earlyRow(): AsyncGenerator<StepEvent> {
+    yield* step([{ kind: "thinking", index: 0, text: "Plan" }, { kind: "text", index: 1, text: "First" }]);
+    file.append([{ type: "thinking", thinking: "Plan", signature: "signature" }]);
+    yield* step([{ kind: "text", index: 1, text: " second" }]);
+    stopped = true;
+    yield* step([stop]);
+  }
+  const text: string[] = [];
+  for await (const event of hostedStreamEvents(earlyRow(), file.rows, 0, "model", async () => serviceFailure, () => {}, () => { progress.push("chunk"); })) {
+    if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
+      expect(stopped).toBe(false);
+      text.push(event.delta.text);
+    }
+  }
+  expect(text).toEqual(["First", " second"]);
+  expect(progress).toEqual(["chunk"]);
+});
+
+test("a row that remains missing after the stop chunk fails transient within the row-write bound", async () => {
+  const file = transcript();
+  let clock = 0;
+  const now = spyOn(Date, "now").mockImplementation(() => (clock += 90_000));
+  let answered = false;
+  try {
+    const output = Array.fromAsync(hostedStreamEvents(step([{ kind: "thinking", index: 0, text: "Plan" }, stop]), file.rows, 0, "model", async () => serviceFailure, () => { answered = true; }, () => {}));
+    const error = await output.catch((failure: unknown) => failure);
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect(error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    expect(answered).toBe(false);
+  } finally {
+    now.mockRestore();
+  }
+});
+
+test("a redacted row can arrive after the stop chunk without row polling reporting synthetic progress", async () => {
+  const file = transcript();
+  const progress: string[] = [];
+  let arriving = "text";
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  /** @yields {StepEvent} The stop precedes the signed row's disk write. */
+  async function* delayedWrite(): AsyncGenerator<StepEvent> {
+    yield* step([{ kind: "text", index: 1, text: "Answer" }]);
+    timer = setTimeout(() => { file.append([{ type: "redacted_thinking", data: "opaque-data" }]); }, 40);
+    arriving = "stop";
+    yield* step([stop]);
+  }
+  try {
+    const output = await Array.fromAsync(hostedStreamEvents(delayedWrite(), file.rows, 0, "model", async () => serviceFailure, () => {}, () => { progress.push(arriving); }));
+    expect(output.slice(1)).toMatchObject([
+      { type: "content_block_start", index: 0, content_block: { type: "redacted_thinking", data: "opaque-data" } },
+      { type: "content_block_stop", index: 0 },
+      { type: "content_block_start", index: 1, content_block: { type: "text" } },
+      { type: "content_block_delta", index: 1, delta: { type: "text_delta", text: "Answer" } },
+      { type: "content_block_stop", index: 1 },
+      { type: "message_delta", delta: { stop_reason: "end_turn" } },
+      { type: "message_stop" },
+    ]);
+    expect(progress).toEqual(["text", "stop"]);
+  } finally {
+    clearTimeout(timer);
+  }
+});
+
+for (const end of ["done", "eof", "error"] as const) {
+  test(`a step that ends with ${end} before its stop preserves its failure while a row is pending`, async () => {
+    const file = transcript();
+    let answered = false;
+    const transportFailure = new Error("connection lost");
+    /** @yields {StepEvent} An incomplete response with no signed row. */
+    async function* incomplete(): AsyncGenerator<StepEvent> {
+      yield* step([{ kind: "thinking", index: 0, text: "Plan" }, { kind: "text", index: 1, text: "Partial" }]);
+      if (end === "done") yield { kind: "done" };
+      if (end === "error") throw transportFailure;
+    }
+    await expect(Array.fromAsync(hostedStreamEvents(incomplete(), file.rows, 0, "model", async () => serviceFailure, () => { answered = true; }, () => {}))).rejects.toBe(end === "error" ? transportFailure : serviceFailure);
+    expect(answered).toBe(false);
+  });
+}
+
+const model: ModelInfo = {
+  provider: "anthropic", family: "anthropic", id: "claude-sonnet-5-5", name: "Claude Sonnet 5.5", reasoning: true, toolCall: true,
+  attachment: true, temperature: true, openWeights: false, cost: { input: 0, output: 0 }, pricing: { status: "unavailable", reason: "missing-rate-card" },
+  modalities: { input: ["text", "image"], output: ["text"] }, contextLimit: 1_000_000, outputLimit: 64_000,
+};
+
+for (const stalled of [false, true]) {
+  test(`the shared adapter ${stalled ? "fails a silent response as a thinking stall" : "keeps a response alive on held chunks past its thinking deadline"}`, async () => {
+    const file = transcript();
+    const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+    process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "100";
+    try {
+      const client = await createAnthropicAdapter(Redacted.make("unused"), model.id, model, {
+        accessProvider: "anthropic_subscription", hosted: true,
+        operations: {
+          isBadRequestError: () => false,
+          async createStream(_params, { signal, onProgress }) {
+            const controller = new AbortController();
+            const requestSignal = AbortSignal.any([signal, controller.signal]);
+            /** @yields {StepEvent} Actual chunks, or silence until the adapter aborts the request. */
+            async function* response(): AsyncGenerator<StepEvent> {
+              yield* step([{ kind: "thinking", index: 0, text: "Plan" }, { kind: "text", index: 1, text: "Answer" }]);
+              if (stalled) await abortableSleep(1_000, requestSignal);
+              for (let i = 0; i < 10; i += 1) {
+                await abortableSleep(20, requestSignal);
+                yield* step([{ kind: "text", index: 1, text: "." }]);
+              }
+              file.append([{ type: "thinking", thinking: "Plan", signature: "signature" }]);
+              yield* step([stop]);
+            }
+            return { data: Object.assign(hostedStreamEvents(response(), file.rows, 0, model.id, async () => serviceFailure, () => {}, () => { onProgress?.(); }), { controller }), response: new Response(null) };
+          },
+        },
+      });
+      const output = Array.fromAsync(client.streamWithTools({ messages: [{ kind: "user", origin: "human", content: "Answer." }], systemPrompt: { stable: "System.", session: "", conversation: "" }, tools: [] }));
+      if (stalled) await expect(output).rejects.toThrow("thinking block stalled");
+      else {
+        const events = await output;
+        expect(events.filter((event) => event.kind === "text_delta").map((event) => event.text).join("")).toBe("Answer..........");
+        expect(events).toContainEqual(expect.objectContaining({ kind: "thinking_complete", thinking: "Plan", signature: "signature" }));
+        expect(events.at(-1)).toMatchObject({ kind: "done", stopReason: "end_turn" });
+      }
+    } finally {
+      if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+      else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+    }
+  });
